namespace detail {

static inline uint32_t rotr(uint32_t x, uint32_t n) {
    return (x >> n) | (x << (32 - n));
}

static std::string sha256_hex(const std::string& data) {
    static const uint32_t K[64] = {
        0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
        0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,
        0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,
        0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,
        0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,
        0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
        0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
        0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
    };

    uint32_t h[8] = {
        0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
        0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19
    };

    std::vector<unsigned char> msg(data.begin(), data.end());
    uint64_t bitlen = static_cast<uint64_t>(msg.size()) * 8;
    msg.push_back(0x80);
    while (msg.size() % 64 != 56) msg.push_back(0x00);
    for (int i = 7; i >= 0; --i)
        msg.push_back(static_cast<unsigned char>((bitlen >> (i * 8)) & 0xFF));

    for (size_t chunk = 0; chunk < msg.size(); chunk += 64) {
        uint32_t w[64];
        for (int i = 0; i < 16; ++i) {
            w[i] = (static_cast<uint32_t>(msg[chunk + i * 4]) << 24) |
                   (static_cast<uint32_t>(msg[chunk + i * 4 + 1]) << 16) |
                   (static_cast<uint32_t>(msg[chunk + i * 4 + 2]) << 8) |
                   (static_cast<uint32_t>(msg[chunk + i * 4 + 3]));
        }
        for (int i = 16; i < 64; ++i) {
            uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
            uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
            w[i] = w[i - 16] + s0 + w[i - 7] + s1;
        }

        uint32_t a = h[0], b = h[1], c = h[2], d = h[3];
        uint32_t e = h[4], f = h[5], g = h[6], hh = h[7];

        for (int i = 0; i < 64; ++i) {
            uint32_t S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
            uint32_t ch = (e & f) ^ ((~e) & g);
            uint32_t temp1 = hh + S1 + ch + K[i] + w[i];
            uint32_t S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
            uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
            uint32_t temp2 = S0 + maj;
            hh = g; g = f; f = e; e = d + temp1;
            d = c; c = b; b = a; a = temp1 + temp2;
        }

        h[0] += a; h[1] += b; h[2] += c; h[3] += d;
        h[4] += e; h[5] += f; h[6] += g; h[7] += hh;
    }

    static const char* hexchars = "0123456789abcdef";
    std::string out;
    out.reserve(64);
    for (int i = 0; i < 8; ++i) {
        for (int j = 3; j >= 0; --j) {
            unsigned char byte = static_cast<unsigned char>((h[i] >> (j * 8)) & 0xFF);
            out += hexchars[byte >> 4];
            out += hexchars[byte & 0xF];
        }
    }
    return out;
}

// Constant-time comparison to avoid timing side channels (CWE-208).
static bool constant_time_equals(const std::string& a, const std::string& b) {
    if (a.size() != b.size()) return false;
    volatile unsigned char diff = 0;
    for (size_t i = 0; i < a.size(); ++i) {
        diff |= static_cast<unsigned char>(a[i]) ^ static_cast<unsigned char>(b[i]);
    }
    return diff == 0;
}

} // namespace detail

class ServiceAuthenticator {
private:
    struct ServiceEntry {
        std::string canonical_name;
        std::string token_hash;
        int trust_level;
    };

    std::vector<ServiceEntry> registered_services_;

    // Internal lookup: finds service by canonical name match
    const ServiceEntry* find_service(const std::string& canonical) const {
        for (const auto& entry : registered_services_) {
            if (entry.canonical_name == canonical)
                return &entry;
        }
        return nullptr;
    }

public:
    void register_service(const std::string& name, const std::string& token_hash, int trust_level) {
        // Registration always uses canonical form
        ServiceEntry entry;
        entry.canonical_name = canonicalize_principal(name);
        entry.token_hash = token_hash;
        entry.trust_level = trust_level;
        registered_services_.push_back(entry);
    }

    // Authenticate a cross-service request
    // Returns trust_level on success, -1 on failure
    int authenticate_request(const std::string& claimed_service, const std::string& token) {
        // Phase 1: Reject ANY non-ASCII in service names
        // This prevents all homograph attacks regardless of script
        if (contains_non_ascii(claimed_service)) {
            return -1;  // Reject any non-ASCII service names
        }

        // Phase 2: Canonicalize and lookup
        std::string canonical = canonicalize_principal(claimed_service);
        const ServiceEntry* service = find_service(canonical);
        if (!service) {
            return -1;
        }

        // Phase 3: Token verification using a cryptographic hash (SHA-256)
        // and a constant-time comparison to prevent timing attacks.
        std::string computed = detail::sha256_hex(token);
        if (!detail::constant_time_equals(computed, service->token_hash)) {
            return -1;
        }

        return service->trust_level;
    }
};

